	/**
	 * Default Constructor
	 */
    public PriceBookService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PriceBookEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PriceBookRepository.class) );
		this.validator		= applicationContext.getBean(PriceBookValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PriceBook
	 */
		public PriceBook createPriceBook( CreatePriceBookCommand command ) {

		PriceBook entity = new PriceBook();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPriceBookId( command.getPriceBookId() );
            entity.setName( command.getName() );
            entity.setAsActive( command.getAsActive() );
            entity.setDescription( command.getDescription() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PriceBook {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePriceBookCommand
	 * @return		PriceBook
	 */
	public PriceBook updatePriceBook( UpdatePriceBookCommand command ) {

		PriceBook entity = new PriceBook();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPriceBookId( command.getPriceBookId() );
            entity.setName( command.getName() );
            entity.setAsActive( command.getAsActive() );
            entity.setDescription( command.getDescription() );
            entity.setOrganization( command.getOrganization() );
            entity.setEntries( command.getEntries() );
            entity.setQuotes( command.getQuotes() );
            entity.setOrders( command.getOrders() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of PriceBook {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePriceBookCommand
	 */
	public void delete( DeletePriceBookCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPriceBookId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of PriceBook {0} ", id );

	}

	/**
	 * Method to retrieve the PriceBook via PriceBookFetchOneSummary
	 * @param 	summary PriceBookFetchOneSummary
	 * @return 	PriceBookFetchOneResponse
	 */
	public PriceBook getPriceBook( PriceBookFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PriceBookFetchOneSummary arg cannot be null" );

		PriceBook entity = null;
		UUID id = summary.getPriceBookId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a PriceBook using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all PriceBooks
	 *
	 * @return 	List<PriceBook>
	 */
    public List<PriceBook> getAllPriceBook() {
		List<PriceBook> list = projector.findAll( new FindAllPriceBookQuery() );
		return list;
	}

	/**
	 * assign Organization on PriceBook
	 * @param		command AssignOrganizationToPriceBookCommand
	 */
	public void assignOrganization( AssignOrganizationToPriceBookCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getPriceBookId(), command.getAssignment());

	}

